Here is the commit message:
wifi: rt2x00usb: fix devres lifetime

USB drivers bind to USB interfaces and any device managed resources
should have their lifetime tied to the interface rather than parent USB
device. This avoids issues like memory leaks when drivers are unbound
without their devices being physically disconnected (e.g. on probe
deferral or configuration changes).

Fix the USB anchor lifetime so that it is released on driver unbind.

Fixes: 8b4c0009313f ("rt2x00usb: Use usb anchor to manage URB")
Cc: stable@vger.kernel.org	# 4.7
Cc: Vishal Thanki <vishalthanki@gmail.com>
Signed-off-by: Johan Hovold <johan@kernel.org>
Acked-by: Stanislaw Gruszka <stf_xl@wp.pl>
Reviewed-by: Greg Kroah-Hartman <gregkh@linuxfoundation.org>
Link: https://patch.msgid.link/20260327113219.1313748-1-johan@kernel.org
Signed-off-by: Johannes Berg <johannes.berg@intel.com>

Here is the root cause:
The USB anchor was allocated using `devm_kmalloc` with the parent USB device (`&usb_dev->dev`) instead of the USB interface (`&usb_intf->dev`). This caused the resource lifetime to be tied to the parent device, so the anchor was not released when the driver unbinds from the interface (e.g., on probe deferral or configuration changes), leading to memory leaks and improper resource cleanup.

Here is the patch:

 int rt2x00usb_probe(struct usb_interface *usb_intf,
 		    const struct rt2x00_ops *ops)
 {
 	struct usb_device *usb_dev = interface_to_usbdev(usb_intf);
 	struct ieee80211_hw *hw;
 	struct rt2x00_dev *rt2x00dev;
 	int retval;

 	usb_dev = usb_get_dev(usb_dev);
 	usb_reset_device(usb_dev);

 	hw = ieee80211_alloc_hw(sizeof(struct rt2x00_dev), ops->hw);
 	if (!hw) {
 		rt2x00_probe_err("Failed to allocate hardware\n");
 		retval = -ENOMEM;
 		goto exit_put_device;
 	}

 	usb_set_intfdata(usb_intf, hw);

 	rt2x00dev = hw->priv;
 	rt2x00dev->dev = &usb_intf->dev;
 	rt2x00dev->ops = ops;
 	rt2x00dev->hw = hw;

 	rt2x00_set_chip_intf(rt2x00dev, RT2X00_CHIP_INTF_USB);

 	INIT_WORK(&rt2x00dev->rxdone_work, rt2x00usb_work_rxdone);
 	INIT_WORK(&rt2x00dev->txdone_work, rt2x00usb_work_txdone);

 	retval = rt2x00usb_alloc_reg(rt2x00dev);
 	if (retval)
 		goto exit_free_device;

-	rt2x00dev->anchor = devm_kmalloc(&usb_dev->dev,
+	rt2x00dev->anchor = devm_kmalloc(&usb_intf->dev,
 					sizeof(struct usb_anchor),
 					GFP_KERNEL);
 	if (!rt2x00dev->anchor) {
 		retval = -ENOMEM;
 		goto exit_free_reg;
 	}
 	init_usb_anchor(rt2x00dev->anchor);

 	retval = rt2x00lib_probe_dev(rt2x00dev);
 	if (retval)
 		goto exit_free_anchor;

 	return 0;

 exit_free_anchor:
 	usb_kill_anchored_urbs(rt2x00dev->anchor);

 exit_free_reg:
 	rt2x00usb_free_reg(rt2x00dev);

 exit_free_device:
 	ieee80211_free_hw(hw);

 exit_put_device:
 	usb_put_dev(usb_dev);

 	usb_set_intfdata(usb_intf, NULL);

 	return retval;
 }
 EXPORT_SYMBOL_GPL(rt2x00usb_probe);


